from typing import List, Tuple, Union

def max_combo(lemonade: int, fries: int, combo_cost: List[Tuple[int, int]], lemonade_per_combo: int, fries_per_combo: int) -> Union[int, Exception]:
    if not all((isinstance(x, int) for x in [lemonade, fries])):
        raise ValueError("Lemonade and fries quantities must be integers.")
    if lemonade < 0 or fries < 0:
        raise ValueError("Lemonade and fries quantities must be non-negative.")

    total_revenue = 0
    while lemonade > 0 and fries > 0:
        for combo, cost in combo_cost:
            if lemonade >= combo[0] and fries >= combo[1]:
                total_revenue += cost
                lemonade -= combo[0]
                fries -= combo[1]
                break
        else:
            break
    return total_revenue if lemonade <= 0 and fries <= 0 else Exception("Not enough resources to sell all combos.")

def max_revenue(lemonade: int, fries: int, combo_cost: List[Tuple[int, int]], price_per_comboA: int, portions_per_comboA: int, price_per_comboB: int, portions_per_comboB: int) -> int:
    if not all((isinstance(x, int) for x in [lemonade, fries, *combo_cost])):
        raise ValueError("Lemonade, fries and combo costs must be integers.")
    if lemonade < 0 or fries < 0:
        raise ValueError("Lemonade and fries quantities must be non-negative.")

    max_revenue = 0
    for combos in range(min(lemonade // portions_per_comboA, min(fries // portions_per_comboB, 180 // portions_per_comboA)), 0, -1):
        comboA = combos * portions_per_comboA
        comboB = fries - combos * portions_per_comboB if (fries - combos * portions_per_comboB) >= 0 else 0
        revenue = price_per_comboA * comboA + price_per_comboB * comboB
        if revenue > max_revenue:
            max_revenue = revenue
    return max_revenue
