        if total_cost > budget:
            return None

        total_revenue = brocade_price * x + mulberry_price * y
        profit = total_revenue - total_cost
        return profit

    def binary_search(left: int, right: int) -> Tuple[int, int]:
        if left > right:
            return None, None

        mid = (left + right) // 2
        result = calculate_profit(mid, max_production - mid)
        if result is not None:
            if calculate_profit(mid + 1, max_production - mid - 1) is None:
                return mid, max_production - mid
        elif calculate_profit(left, mid - 1) is not None:
            return binary_search(left, mid - 1)
        else:
            return binary_search(mid + 1, right)

    x, y = binary_search(0, max_production)
    if x and y:
        return x + 3 * y
    else:
        return None
