    def __init__(self, wood_limit: int, labor_hours: int):
        self.wood_limit = wood_limit
        self.labor_hours = labor_hours
        self.tables = 0
        self.chairs = 0
        self.remaining_wood = wood_limit
        self.remaining_labor = labor_hours

    def produce(self, product: 'Product') -> Optional[int]:
        if self.remaining_wood < product.wood_req or self.remaining_labor < product.labor_req:
            return None

        self.remaining_wood -= product.wood_req
        self.remaining_labor -= product.labor_req

        if isinstance(product, Table):
            self.tables += 1
        else:
            self.chairs += 1

        return 1

class Table(Product):
    def __init__(self):
        super().__init__(5, 2, 600_000)

class Chair(Product):
    def __init__(self):
        super().__init__(2, 1, 300_000)

def max_profit(wood: int, labor: int, table_req: int, chair_req: int, table_profit: int, chair_profit: int) -> float:
    workshop = Workshop(wood, labor)
    table = Table()
    chair = Chair()

    while True:
