            wood_used = min(workshop.remaining_wood // table_req, workshop.tables) * table.wood_req
            labor_used = min(workshop.remaining_labor // chair_req, workshop.chairs) * chair.labor_req
            workshop.remaining_wood -= wood_used
            workshop.remaining_labor -= labor_used
            workshop.tables -= (workshop.remaining_wood // table_req if workshop.remaining_wood % table_req != 0 else workshop.tables + 1)
            workshop.chairs -= (workshop.remaining_labor // chair_req if workshop.remaining_labor % chair_req != 0 else workshop.chairs + 1)

