from itertools import combinations_with_replacement, permutations

def count_rotor_arrangements(n: int, masses: list) -> int:
    if n < 3 or len(masses) != n:
        return 0

    group_sizes = 3
    groups = [[] for _ in range(group_sizes)]

    # Divide the masses into groups of equal total mass
    for i in range(n):
        group = next((g for g in combinations_with_replacement(masses, group_sizes) if sum(g) == n // group_sizes), None)
        if group is None:
            return 0
        groups[i % group_sizes] = list(group)

    # Check if the groups can be arranged in equilateral triangles
    triangle_slots = [(i, i + 3 * j % n, i + 2 * 3 * j % n) for i in range(n) for j in range(1, group_sizes)]
    permutations_count = sum(1 for _ in permutations(triangle_slots, len(triangle_slots)))

    # Count unique arrangements (rotations and reflections are considered distinct)
    return permutations_count * factorial(n) ** (group_sizes - 1)

def factorial(n: int) -> int:
    if n == 0:
        return 1
    return n * factorial(n - 1)
