def cubic_function(a: float, b: float, c: float, d: float) -> callable:
    """Cubic function y = f(x) with coefficients a, b, c, and d."""
    def f(x: float) -> float:
        if x <= -1:
            return np.nan
        return a * x**3 + b * x**2 + c * x + d
    return f

def road(x: float) -> float:
    """Road function g(x) = (x + 1)/(x - 2) for x > 2."""
    if x <= 2:
        return np.nan
    return (x + 1) / (x - 2)

def distance_to_line(point: Tuple[float, float], line: callable, epsilon: float = 1e-6) -> float:
    """Distance from a point to a line."""
    x, y = point
    m, b = np.polyfit(np.array([0, 1]), np.array([line(0), line(1)]), 1)
    return abs((m * x + b - y) / math.sqrt(m**2 + 1))

def find_min_distance(cubic: callable, road: callable, epsilon: float = 1e-6) -> float:
    """Find the shortest distance from a point M (the garden's boundary) to the road g(x)."""
    def gradient(f: callable, g: callable) -> callable:
        def h(x: float) -> float:
            return (g(x) - f(x)) / (g'(x) - f'(x)) if g'(x) != f'(x) else np.nan
        return h

    def newton_raphson(f: callable, df: callable, initial_guess: float, epsilon: float = 1e-6) -> float:
        x = initial_guess
        while True:
            y = f(x)
            if math.isnan(y):
                return np.nan
            dy = df(x)
            if abs(y) < epsilon or abs(dy) < epsilon:
                break
            x -= y / dy
        return x

    def find_point_on_cubic(cubic: callable, road: callable) -> Tuple[float, float]:
        """Find the point on the cubic curve closest to the road."""
        def f(x: float) -> float:
            return distance_to_line((x, cubic(x)), road)

        def df(x: float) -> float:
            return -distance_to_line((x, cubic(x)), gradient(cubic, road))

        x = newton_raphson(f, df, 0.5)
        return (x, cubic(x))

