def count_blue_triangles(n: int) -> int:
    edges = set()
    diagonals = set()

    # Generate all possible edges and diagonals of the polygon
    for i in range(1, n):
        for j in range(i + 1, n):
            edges.add((i, j))
            if (n - i - j) > 0:
                diagonals.add((i, j, n - i - j))

    # Count the number of blue triangles (those with all three sides as edges)
    blue_triangles = len(edges)

    # Count the number of red triangles (those with one side as an edge and two sides as diagonals)
    for triangle in diagonals:
        a, b, c = triangle
        if (a - 1, b - 1), (b - 1, c - 1), (c - 1, a - 1) in edges:
