    red_triangles = len(list(diagonals for diagonals in combinations(range(1, n), 3) if all((diagonal - 1, diagonal[0] - 1, diagonal[-1] - 1) in edges for diagonal in diagonals)))
    return Fraction(total - red_triangles, total)

