from typing import List, Dict, Union
import math

def factorial(n: int) -> int:
    if n == 0 or n == 1:
        return 1
    result = 1
    for i in range(2, n + 1):
        result *= i
    return result

def choose(n: int, k: int) -> int:
    return math.factorial(n) // (math.factorial(k) * math.factorial(n - k))

def calculate_color_combinations(colors: List[int], n: int) -> Dict[str, int]:
    combinations = {frozenset(sorted(comb)): choose(n, len(comb)) for comb in itertools.combinations(colors, n)}
    return combinations

def calculate_number_of_valid_placements(colors: List[List[int]], nums: List[List[int]], n: int) -> int:
    valid_placements = 0
    for color in colors:
        for num in nums:
            if len(color) != len(num):
                continue
            combination = frozenset(sorted(set(color + num)))
            if combination in valid_combinations:
                valid_placements += valid_combinations[combination]
    return valid_placements

def calculate_final_value(n: int) -> Union[int, float]:
    colors = [list(range(1, 5)) for _ in range(3)]
    valid_combinations = calculate_color_combinations(colors, n)
    octahedron_faces = list(itertools.permutations([0, 1, 2, 3], 8))
    total_placements = 0
    for faces in octahedron_faces:
        color_combinations = []
        num_combinations = []
        for i in range(len(faces)):
            if i % 2 == 1:
                color_combinations.append([colors[j][faces[i]] for j in range(3)] if faces[i] != 0 else [])
            elif i > 0 and faces[i - 1] != faces[i]:
                num_combinations.append([nums[j][faces[i]] for j in range(3)] if faces[i] != 0 else [])
        total_placements += calculate_number_of_valid_placements(color_combinations, num_combinations, n)
    return (total_placements / len(octahedron_faces)) + 16
